; Generated by gbstage from "Bands". Changes here are overwritten on the next build.

DEF rP1    EQU $FF00
DEF rIF    EQU $FF0F
DEF rLCDC  EQU $FF40
DEF rSCY   EQU $FF42
DEF rSCX   EQU $FF43
DEF rLY    EQU $FF44
DEF rBGP   EQU $FF47
DEF rOBP0  EQU $FF48
DEF rVBK   EQU $FF4F
DEF rHDMA1 EQU $FF51
DEF rHDMA2 EQU $FF52
DEF rHDMA3 EQU $FF53
DEF rHDMA4 EQU $FF54
DEF rHDMA5 EQU $FF55
DEF rBCPS  EQU $FF68
DEF rBCPD  EQU $FF69
DEF rOCPS  EQU $FF6A
DEF rOCPD  EQU $FF6B
DEF rIE    EQU $FFFF
DEF OAM_CURSOR EQU $FE00

DEF MAP_W EQU 20
DEF MAP_H EQU 18

SECTION "Header", ROM0[$100]
    nop
    jp Start
    ds $150 - @, 0

SECTION "Code: Start", ROM0
Start:
    ld b, a                 ; the boot ROM leaves A = $11 on Game Boy Color hardware
.waitVBlank:                ; the LCD may only be switched off during VBlank
    ldh a, [rLY]
    cp 144
    jr c, .waitVBlank
.waitVBlankDone:            ; labels named .waitX/.waitXDone mark idle loops for the profiler
    xor a
    ldh [rLCDC], a
    ld a, b
    cp $11
    jp nz, .original

    ; Game Boy Color: DMA the tiles, map and palette map, then load the palettes this screen uses.
    ld a, HIGH(Scene0Tiles + 0)
    ldh [rHDMA1], a
    ld a, LOW(Scene0Tiles + 0)
    ldh [rHDMA2], a
    ld a, HIGH($9000 + 0)
    ldh [rHDMA3], a
    ld a, LOW($9000 + 0)
    ldh [rHDMA4], a
    ld a, 3
    ldh [rHDMA5], a         ; 64 bytes; the CPU waits 128 cycles
    ld a, HIGH(Scene0Map + 0)
    ldh [rHDMA1], a
    ld a, LOW(Scene0Map + 0)
    ldh [rHDMA2], a
    ld a, HIGH($9800 + 0)
    ldh [rHDMA3], a
    ld a, LOW($9800 + 0)
    ldh [rHDMA4], a
    ld a, 35
    ldh [rHDMA5], a         ; 576 bytes; the CPU waits 1152 cycles
    ld a, 1
    ldh [rVBK], a
    ld a, HIGH(Scene0Attr + 0)
    ldh [rHDMA1], a
    ld a, LOW(Scene0Attr + 0)
    ldh [rHDMA2], a
    ld a, HIGH($9800 + 0)
    ldh [rHDMA3], a
    ld a, LOW($9800 + 0)
    ldh [rHDMA4], a
    ld a, 35
    ldh [rHDMA5], a         ; 576 bytes; the CPU waits 1152 cycles
    xor a
    ldh [rVBK], a
    ld hl, BgPalettes
    ld c, LOW(rBCPD)
    ld a, $80 | 0
    ldh [rBCPS], a
    ld b, 3
.palettes0:
    REPT 8
        ld a, [hl+]
        ldh [c], a
    ENDR
    dec b
    jr nz, .palettes0
    jp .show

.original:                  ; original Game Boy: pop the data off the stack, 2 bytes at a time
    ld sp, Scene0Tiles
    ld hl, $9000            ; tiles 0-127
    ld b, 4
.tiles:
    REPT 8
        pop de
        ld a, e
        ld [hl+], a
        ld a, d
        ld [hl+], a
    ENDR
    dec b
    jr nz, .tiles
    ld sp, Scene0Map
    ld hl, $9800
    ld b, MAP_H
.mapRow:
    REPT MAP_W / 2
        pop de
        ld a, e
        ld [hl+], a
        ld a, d
        ld [hl+], a
    ENDR
    add sp, 32 - MAP_W      ; skip the off-screen padding
    ld a, l                 ; HL += 32 - MAP_W
    add 32 - MAP_W
    ld l, a
    adc h
    sub l
    ld h, a
    dec b
    jr nz, .mapRow
    ld a, %11100100         ; slot 0 white ... slot 3 black
    ldh [rBGP], a           ; (nothing below uses the stack, so SP can stay where the copy left it)

.show:
    xor a
    ldh [rSCY], a
    ldh [rSCX], a
    ld a, %10000001
    ldh [rLCDC], a
    ld a, 1                 ; VBlank wakes HALT; interrupts stay disabled, so no handler runs
    ldh [rIE], a
MainLoop:
    xor a
    ldh [rIF], a
    halt
    nop                     ; HALT may run the next byte twice if VBlank arrives just before it
    jr MainLoop

SECTION "Data: Palettes", ROM0
BgPalettes:                 ; RGB555
    dw $7FFF, $7F54, $7208, $3082  ; Sky
    dw $63FC, $2B31, $21E6, $10A1  ; Grass
    dw $5B9F, $223D, $10F1, $0846  ; Brick

SECTION "Data: Scene 0 tiles", ROM0, ALIGN[4]   ; DMA needs 16-byte alignment
Scene0Tiles:              ; "Main": 4 unique tiles
    db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
    db $FF, $00, $FF, $00, $FF, $00, $FF, $00, $FF, $00, $FF, $00, $FF, $00, $FF, $00
    db $00, $FF, $00, $FF, $00, $FF, $00, $FF, $00, $FF, $00, $FF, $00, $FF, $00, $FF
    db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF

